const tri = (ru: string, uk: string, es: string, planned: Partial<Record<keyof typeof PLANNED_LOCALE_FALLBACK, string>> = {}): TriText => ({
  ru,
  uk,
  es,
  'pt-BR': planned['pt-BR'] ?? PLANNED_LOCALE_FALLBACK['pt-BR'],
  vi: planned.vi ?? PLANNED_LOCALE_FALLBACK.vi,
  id: planned.id ?? PLANNED_LOCALE_FALLBACK.id,
  tr: planned.tr ?? PLANNED_LOCALE_FALLBACK.tr,
  pl: planned.pl ?? PLANNED_LOCALE_FALLBACK.pl,
});

function doStep(input: {
  id: string;
  order: number;
  difficulty: DiagnosisTrainingStep['difficulty'];
  targetSkill: string;
  sentence: string;
  translation: TriText;
  options: string[];
  correctAnswer: string;
  correctFeedback: TriText;
  wrong: Record<string, TriText>;
  retry: [TriText, TriText, TriText];
  focusWords: string[];
}): DiagnosisTrainingStep {
  const correctIndex = input.options.findIndex((option) => option === input.correctAnswer);
  return {
    id: input.id,
    order: input.order,
    difficulty: input.difficulty,
    type: 'single_choice',
    targetSkill: input.targetSkill,
    translation: input.translation,
    explanationBlock: tri(
      'В Present Simple does уже забирает -s на себя. После do/does/don’t/doesn’t основной глагол идет в простой форме: work, like, know.',
      'У Present Simple does уже забирає -s на себе. Після do/does/don’t/doesn’t основне дієслово йде в простій формі: work, like, know.',
      'En Present Simple, does ya toma la -s. Después de do/does/don’t/doesn’t el verbo principal va en base form.',
      {
        'pt-BR': 'No Present Simple, does já carrega o -s. Depois de do/does/don’t/doesn’t, o verbo principal vai em base form.',
        vi: 'Trong Present Simple, does đã mang -s. Sau do/does/don’t/doesn’t, động từ chính ở base form.',
        id: 'Dalam Present Simple, does sudah membawa -s. Setelah do/does/don’t/doesn’t, verba utama memakai base form.',
        tr: 'Present Simple içinde does zaten -s taşır. do/does/don’t/doesn’t sonrasında ana fiil base form olur.',
        pl: 'W Present Simple does już niesie -s. Po do/does/don’t/doesn’t główny czasownik jest w base form.',
      },
    ),
    microTask: tri('Выбери правильную форму do/does или основного глагола.', 'Обери правильну форму do/does або основного дієслова.', 'Elige la forma correcta de do/does o del verbo principal.', {
      'pt-BR': 'Escolha a forma correta de do/does ou do verbo principal.',
      vi: 'Chọn dạng đúng của do/does hoặc động từ chính.',
      id: 'Pilih bentuk do/does atau verba utama yang benar.',
      tr: 'do/does veya ana fiilin doğru biçimini seç.',
      pl: 'Wybierz poprawną formę do/does albo głównego czasownika.',
    }),
    sentence: input.sentence,
    answerOptions: input.options.map((text) => ({ id: text, text })),
    correctAnswerId: input.correctAnswer,
    correctIndex,
    correctFeedback: input.correctFeedback,
    wrongFeedbackByOption: Object.fromEntries(input.options
      .filter((option) => option !== input.correctAnswer)
      .map((option) => [option, input.wrong[option] ?? tri(
        'Не совсем. Проверь, кто делает действие: he/she/it = does/doesn’t. После do/does глагол идет без -s.',
        'Не зовсім. Перевір, хто робить дію: he/she/it = does/doesn’t. Після do/does дієслово йде без -s.',
        'No exactamente. Revisa subject y verbo principal: he/she/it = does/doesn’t, después de auxiliary el verbo va sin -s.',
        {
          'pt-BR': 'Não exatamente. Verifique subject e verbo principal: he/she/it = does/doesn’t; depois do auxiliary, o verbo vai sem -s.',
          vi: 'Chưa hẳn. Kiểm tra subject và động từ chính: he/she/it = does/doesn’t; sau auxiliary, động từ không có -s.',
          id: 'Belum tepat. Periksa subject dan verba utama: he/she/it = does/doesn’t; setelah auxiliary, verba tanpa -s.',
          tr: 'Tam değil. Subject ve ana fiili kontrol et: he/she/it = does/doesn’t; auxiliary sonrasında fiil -s almaz.',
          pl: 'Nie do końca. Sprawdź subject i główny czasownik: he/she/it = does/doesn’t; po auxiliary czasownik jest bez -s.',
        },
      )])),
    retryFeedback: [
      input.retry[0],
      input.retry[1],
      input.retry[2],
      tri(
        `Подсказка: правильный блок - "${input.correctAnswer}".`,
        `Підказка: правильний блок - "${input.correctAnswer}".`,
        `Pista: el bloque correcto es "${input.correctAnswer}".`,
        {
          'pt-BR': `Dica: o bloco correto é "${input.correctAnswer}".`,
          vi: `Gợi ý: khối đúng là "${input.correctAnswer}".`,
          id: `Petunjuk: blok yang benar adalah "${input.correctAnswer}".`,
          tr: `İpucu: doğru blok "${input.correctAnswer}".`,
          pl: `Podpowiedź: poprawny blok to "${input.correctAnswer}".`,
        },
      ),
    ],
    fallbackExplanation: tri(
      'Сначала найди, кто делает действие. He/she/it берут does или doesn’t. I/you/we/they берут do или don’t. После этого глагол без -s.',
      'Спочатку знайди, хто робить дію. He/she/it беруть does або doesn’t. I/you/we/they беруть do або don’t. Після цього дієслово без -s.',
      'Primero subject: he/she/it -> does/doesn’t. I/you/we/they -> do/don’t. Después de auxiliary siempre base verb: work, like, know.',
      {
        'pt-BR': 'Primeiro subject: he/she/it -> does/doesn’t. I/you/we/they -> do/don’t. Depois do auxiliary, sempre base verb: work, like, know.',
        vi: 'Trước tiên subject: he/she/it -> does/doesn’t. I/you/we/they -> do/don’t. Sau auxiliary luôn là base verb: work, like, know.',
        id: 'Pertama subject: he/she/it -> does/doesn’t. I/you/we/they -> do/don’t. Setelah auxiliary selalu base verb: work, like, know.',
        tr: 'Önce subject: he/she/it -> does/doesn’t. I/you/we/they -> do/don’t. Auxiliary sonrasında her zaman base verb: work, like, know.',
        pl: 'Najpierw subject: he/she/it -> does/doesn’t. I/you/we/they -> do/don’t. Po auxiliary zawsze base verb: work, like, know.',
      },
    ),
    focusWords: input.focusWords,
  };
}

